func subscriptionTier(id string) (SubscriptionTier, bool) {
	for _, p := range subscriptionTiers() {
		if p.ID == id {
			return p, true
		}
	}
	return SubscriptionTier{}, false
}

func planForWindow(c ProfileConfig, w Window) string {
	for _, p := range c.Plans {
		if p.Account == w.Account && p.Start <= w.Start && (p.End == 0 || p.End >= w.AttributionEnd) {
			return p.Plan
		}
	}
	return ""
}

type TierComparison struct {
	Tier    SubscriptionTier `json:"tier"`
	Percent *float64         `json:"percent"`
	Status  string           `json:"status"`
	Reason  string           `json:"reason"`
	Ratio   *float64         `json:"capacity_ratio,omitempty"`
}

func compareSubscription(w Window, sourceID string, used *float64, basis string, targetID string, customRatio float64) []TierComparison {
	out := []TierComparison{}
	source, sourceOK := subscriptionTier(sourceID)
	for _, target := range subscriptionTiers() {
		c := TierComparison{Tier: target, Status: "unavailable"}
		switch {
		case used == nil:
			c.Reason = "A complete quota contribution for this selection is unavailable."
		case w.BoundaryRevision:
			c.Reason = "This window has a revised reset boundary."
		case customRatio > 0 && targetID == target.ID:
			if *used >= 100 {
				c.Reason = "The saturated source meter cannot quantify usage beyond the allowance."
				break
			}
			v := *used / customRatio
			c.Percent, c.Ratio, c.Status = &v, &customRatio, "scenario"
			c.Reason = "Your assumed target/source capacity ratio for this window; equivalent workload, timing and model availability are not verified."
		case !sourceOK || source.Provider != w.Provider:
			c.Reason = "Set the source subscription for this credential and period."
		case source.ID == target.ID:
			v := *used
			c.Percent, c.Status, c.Reason = &v, "same_tier", "Same source tier and metering policy."
		case source.Provider != target.Provider:
			c.Reason = "No verified cross-platform quota conversion. API-equivalent cost remains available."
		case source.Scope != w.Scope || target.Scope != w.Scope:
			c.Reason = "The published ratio does not cover this quota pool."
		case basis == "then" && (w.Start < source.RulesFrom || w.Start < target.RulesFrom):
			c.Reason = "No verified tier rule for this historical date. Choose current benchmarks or an explicit scenario."
		default:
			sf, tf := source.Session, target.Session
			if w.Kind == "weekly" {
				sf, tf = source.Weekly, target.Weekly
			} else if w.Kind != "5h" {
				sf, tf = 0, 0
			}
			if sf <= 0 || tf <= 0 {
				c.Reason = "No published capacity ratio for this window. A session multiplier does not establish a weekly allowance."
			} else if *used >= 100 {
				c.Reason = "The saturated source meter cannot quantify usage beyond the allowance."
			} else {
				ratio := tf / sf
				v := *used / ratio
				c.Percent, c.Ratio, c.Status = &v, &ratio, "estimate"
				c.Reason = "Published pool/window ratio; assumes the same eligible workload and metering policy. This is a window comparison, not a replay of a different reset schedule."
			}
		}
		out = append(out, c)
	}
	return out
}

func validCapacityRatio(v float64) bool {
	return !math.IsNaN(v) && !math.IsInf(v, 0) && v >= 0 && v <= 10000
}
